/**
 * Archive search controller.
 *
 * Thin wrapper over api::article.article's searchArchive - the desk UI hits
 * this while the reader types, so it has to stay cheap.
 */
import { factories } from "@strapi/strapi";

import { resolveMembership } from "../../../utils/access";

const MIN_TERM_LENGTH = 2;

export default factories.createCoreController("api::article.article", ({ strapi }) => ({
  async find(ctx) {
    const membership = await resolveMembership(ctx);
    if (!membership?.organisationId) {
      return ctx.unauthorized("No organisation on this account");
    }

    const term = String(ctx.query.q ?? "");
    if (term.trim().length < MIN_TERM_LENGTH) {
      return ctx.badRequest("q must be at least two characters");
    }

    const rows = await strapi.service("api::article.article").searchArchive({
      term,
      sortBy: ctx.query.sort as string | undefined,
      direction: ctx.query.direction as string | undefined,
      limit: ctx.query.limit as string | undefined,
      organisationId: membership.organisationId,
    });

    ctx.body = { data: rows, meta: { count: rows.length } };
  },
}));

